function normaliseName(v){return String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function matchExercise(name){const aliases={'chest fly':'Cable Fly','bench press':'Barbell Bench Press','biceps curl':'Dumbbell Biceps Curl','shoulder press':'Shoulder Press Machine','triceps':'Cable Triceps Pushdown','lat pull downs':'Lat Pulldown','lat pulldowns':'Lat Pulldown','leg raises':'Leg Raise'};const n=normaliseName(name),target=normaliseName(aliases[n]||name);return EXERCISES.find(e=>normaliseName(e.name)===target)}
function parseSave(raw){try{const x=JSON.parse(raw||'null');return x&&typeof x==='object'?x:null}catch{return null}}
function loggedDayCount(x){return x&&x.days&&typeof x.days==='object'?Object.keys(x.days).length:0}
function loadState(){const keys=['cq3','cq3_pre_import_backup','cq3_backup'],candidates=keys.map(k=>({key:k,data:parseSave(localStorage.getItem(k))})).filter(x=>x.data&&x.data.days);if(candidates.length){candidates.sort((a,b)=>loggedDayCount(b.data)-loggedDayCount(a.data));const best=candidates[0];if(best.key!=='cq3'&&loggedDayCount(best.data)>loggedDayCount(parseSave(localStorage.getItem('cq3')))){localStorage.setItem('cq3_recovered_from',best.key);localStorage.setItem('cq3',JSON.stringify(best.data))}return best.data}const state=emptyState(),old=parseSave(localStorage.getItem('cq'));if(!old)return state;const migrated=blank();migrated.protein=Number(old.protein??migrated.protein);migrated.steps=Number(old.steps??migrated.steps);migrated.calories=Number(old.calories??migrated.calories);migrated.proteinTarget=Number(old.proteinTarget??150);migrated.stepTarget=Number(old.stepTarget??10000);migrated.exercises=(old.exercises||[]).map(e=>{const m=matchExercise(e.name);return m?{id:m.id,sets:Number(e.sets)||0,reps:Number(e.reps)||0,weight:Number(e.weight)||0,unit:e.unit||'kg',effort:null}:null}).filter(Boolean);state.days[migrated.date]=migrated;localStorage.setItem('cq3',JSON.stringify(state));return state}
