function daysBetween(a,b){return Math.max(0,Math.floor((new Date(b)-new Date(a))/86400000))}
function lastActivity(skill){const rows=Object.values(d.days).filter(z=>skill==='agility'?z.steps>0:skill==='strength'?(z.exercises||[]).length:z.cardio?.id).sort((a,b)=>b.date.localeCompare(a.date));return rows[0]?.date||null}
function applyDeconditioning(){['agility','endurance','strength'].forEach(k=>{const last=lastActivity(k);if(!last)return;const away=daysBetween(last,key());if(away>90)d.form[k]=Math.min(d.form[k],Math.max(50,100-Math.ceil((away-90)/30)*10))})}
function efficiency(form){return form>=90?1:form>=75?.95:form>=50?.90:.85}
