function tier(v,t,a,b,c){let r=t?(+v||0)/t:0;return r>=1?c:r>=.8?b:r>=.6?a:0}function calcLevel(x,cap){x=Math.max(0,Math.min(x,cap));let r=x/cap;return Math.min(99,r<.6?1+Math.floor(83*Math.pow(r/.6,1/1.35)):84+Math.floor(15*Math.sqrt((r-.6)/.4)))}
function levelThreshold(n,cap){if(n<=1)return 0;if(n<=84)return cap*.6*Math.pow((n-1)/83,1.35);return cap*(.6+.4*Math.pow((n-84)/15,2))}
function levelProgress(x,cap){x=Math.max(0,Math.min(Number(x)||0,cap));const level=calcLevel(x,cap);if(level>=99)return{level,needed:0,pct:100,next:cap};const start=Math.ceil(levelThreshold(level,cap)),next=Math.ceil(levelThreshold(level+1,cap));return{level,needed:Math.max(1,next-x),pct:Math.max(0,Math.min(100,Math.round(100*(x-start)/Math.max(1,next-start)))),next}}
function proteinXP(actual,target){if(!target||actual==null)return 0;const r=Number(actual)/Number(target);if(r<.6)return 0;if(r>=1)return 40;if(r>=.95)return 38;if(r>=.9)return 35;if(r>=.85)return 32;if(r>=.8)return 30;if(r>=.75)return 25;if(r>=.7)return 20;if(r>=.65)return 15;return 10}
function calorieXP(actual,target){if(!target||actual==null||Number(actual)<=0)return 0;const delta=Math.abs(Number(actual)-Number(target))/Number(target);return delta<=.05?50:delta<=.10?35:delta<=.15?20:0}
