function bestNextAction(x){const options=[];const stepNow=Number(day.steps)||0;if(stepNow<10000){const nextStep=stepNow<3500?3500:Math.min(10000,3500+(Math.floor((stepNow-3500)/500)+1)*500),gain=scaledXP(agilityStepXP(nextStep)-agilityStepXP(stepNow),'agility');options.push({gain,label:`Walk ${Math.max(0,nextStep-stepNow).toLocaleString()} more steps to reach ${nextStep.toLocaleString()}`,skill:'Agility'});}const pr=day.proteinTarget?day.protein/day.proteinTarget:0;if(pr<1){const bands=[.6,.65,.7,.75,.8,.85,.9,.95,1],next=bands.find(b=>pr<b)||1,nextG=Math.ceil(day.proteinTarget*next),gain=scaledXP(proteinXP(nextG,day.proteinTarget)-proteinXP(day.protein,day.proteinTarget),'nutrition');if(gain>0)options.push({gain,label:`Log ${Math.max(0,nextG-day.protein)} g more protein to reach ${Math.round(next*100)}% of your target`,skill:'Nutrition'});}if(Number(day.fruitVeg)<5)options.push({gain:scaledXP(10,'nutrition'),label:`Add ${5-Number(day.fruitVeg||0)} fruit/veg portion${5-Number(day.fruitVeg||0)===1?'':'s'}`,skill:'Nutrition'});if(!day.calories)options.push({gain:scaledXP(50,'nutrition'),label:'Log calories within your personal target band',skill:'Nutrition'});if(!day.cardio?.id)options.push({gain:scaledXP(40,'endurance'),label:'Log a 20-minute accessible cardio session',skill:'Endurance'});if(!(day.exercises||[]).length)options.push({gain:scaledXP(10,'strength'),label:'Log your first strength exercise',skill:'Strength'});return options.filter(o=>o.gain>0).sort((a,b)=>b.gain-a.gain)[0]||{gain:0,label:'Today is fully logged. Recovery is part of the plan.',skill:'Health'}}
function agilityStepXP(steps){steps=Number(steps)||0;if(steps<3500)return 0;if(steps>=10000)return 100;const band=Math.floor((steps-3500)/500);return [10,15,20,25,30,35,40,50,60,70,80,85,90][Math.min(12,band)]}
function prior(ex){return Object.values(d.days).filter(x=>x.date!==day.date).flatMap(x=>x.exercises||[]).filter(x=>x.id===ex.id&&x.unit===ex.unit).pop()}
function strength(){let v=day.exercises.filter(e=>e.sets>0&&e.reps>0&&(e.unit==='bodyweight'||e.weight>=0)),raw=v.reduce((s,e)=>s+(EXERCISES.find(x=>x.id===e.id)?.xp||0),0)+(v.length>=7?6:v.length>=4?3:0),p=0;v.forEach(e=>{let q=prior(e);if(q&&e.unit!=='bodyweight'&&e.weight&&q.weight&&p<6&&e.sets*e.reps*e.weight>=q.sets*q.reps*q.weight*1.025){raw+=2;p+=2}});return {account:Math.min(100,raw),mastery:Math.min(15,Math.max(0,raw-100)),raw}}
function enduranceScore(){if(!day.cardio?.id||day.cardio.minutes<10)return{account:0,mastery:0,raw:0};let a=CARDIO.find(x=>x.id===day.cardio.id),m=day.cardio.minutes<20?.5:day.cardio.minutes<30?.75:day.cardio.minutes<45?1:day.cardio.minutes<60?1.15:1.25,r=day.cardio.effort<=3?.8:day.cardio.effort<=6?1:1.1,raw=Math.round(a.xp*m*r);return{account:Math.min(100,raw),mastery:Math.min(15,Math.max(0,raw-100)),raw}}
function calc(){let sc=strength(),ec=enduranceScore(),f=day.formEfficiency||{agility:1,endurance:1,strength:1},rawAgility=Math.round(agilityStepXP(day.steps)*f.agility),rawEndurance=Math.round(ec.account*f.endurance),rawStrength=Math.round(sc.account*f.strength),rawNutrition=Math.min(100,proteinXP(day.protein,day.proteinTarget)+calorieXP(day.calories,day.calorieTarget)+(Number(day.fruitVeg)>=5?10:0)),rawActive=rawAgility+rawEndurance+rawStrength+rawNutrition,rawHealth=Math.min(80,Math.round(.25*rawActive));return{agility:scaledXP(rawAgility,'agility'),endurance:scaledXP(rawEndurance,'endurance'),strength:scaledXP(rawStrength,'strength'),nutrition:scaledXP(rawNutrition,'nutrition'),health:scaledXP(rawHealth,'health'),total:scaledXP(rawAgility,'agility')+scaledXP(rawEndurance,'endurance')+scaledXP(rawStrength,'strength')+scaledXP(rawNutrition,'nutrition')+scaledXP(rawHealth,'health'),rawActive,raw:{agility:rawAgility,endurance:rawEndurance,strength:rawStrength,nutrition:rawNutrition,health:rawHealth},consistent:rawActive>=60,mastery:{agility:f.agility===1&&day.steps>=day.stepTarget*1.5?10:0,endurance:f.endurance===1?ec.mastery:0,strength:f.strength===1?sc.mastery:0}}}
