function toggleFavourite(kind){const sel=kind==='exercise'?ename:cardioActivity,id=sel.value;if(!id)return;const p=activityPrefs(),k=kind==='exercise'?'favouriteExercises':'favouriteCardio';p[k]=p[k].includes(id)?p[k].filter(x=>x!==id):[...p[k],id];saveActivityPrefs(p);buildActivityMenus(id,kind)}
function addGroup(select,label,items,labelFn){if(!items.length)return;const g=document.createElement('optgroup');g.label=label;items.forEach(e=>g.appendChild(new Option(labelFn(e),e.id)));select.appendChild(g)}
function buildActivityMenus(selectedId='',changedKind=''){
 const p=activityPrefs(),exCurrent=changedKind==='exercise'?selectedId:ename.value,caCurrent=changedKind==='cardio'?selectedId:cardioActivity.value;
 const strengthIntensity={major:{rank:0,label:'Major movement'},standard:{rank:1,label:'Standard movement'},isolation:{rank:2,label:'Accessory movement'}};
 ename.innerHTML='';addGroup(ename,'★ Favourites',p.favouriteExercises.map(id=>EXERCISES.find(e=>e.id===id)).filter(Boolean),e=>`${e.name} · ${strengthIntensity[e.type]?.label||'Exercise'}`);addGroup(ename,'↻ Recently used',p.recentExercises.map(id=>EXERCISES.find(e=>e.id===id)).filter(Boolean),e=>`${e.name} · ${strengthIntensity[e.type]?.label||'Exercise'}`);[...new Set(EXERCISES.map(e=>e.group))].forEach(group=>addGroup(ename,group,EXERCISES.filter(e=>e.group===group).sort((a,b)=>(strengthIntensity[a.type]?.rank??9)-(strengthIntensity[b.type]?.rank??9)||a.name.localeCompare(b.name)),e=>`${e.name} · ${strengthIntensity[e.type]?.label||'Exercise'}`));if(exCurrent)ename.value=exCurrent;
 const enduranceLabels={high:'High intensity · hard sustained work or intervals',strong:'Strong intensity · challenging cardio',moderate:'Moderate intensity · steady purposeful exercise',accessible:'Accessible intensity · gentle or recovery movement'};
 cardioActivity.innerHTML='';cardioActivity.add(new Option('No cardio session',''));addGroup(cardioActivity,'★ Favourites',p.favouriteCardio.map(id=>CARDIO.find(e=>e.id===id)).filter(Boolean),e=>`${e.name} · ${enduranceLabels[e.type].split(' · ')[0]}`);addGroup(cardioActivity,'↻ Recently used',p.recentCardio.map(id=>CARDIO.find(e=>e.id===id)).filter(Boolean),e=>`${e.name} · ${enduranceLabels[e.type].split(' · ')[0]}`);['high','strong','moderate','accessible'].forEach(type=>addGroup(cardioActivity,enduranceLabels[type],CARDIO.filter(e=>e.type===type).sort((a,b)=>a.name.localeCompare(b.name)),e=>e.name));if(caCurrent)cardioActivity.value=caCurrent;updateFavouriteButtons();
}
