function renderProgressChart(){const el=document.getElementById('progressChart'),metric=document.getElementById('progressMetric')?.value||'weight',hist=(d.profile.measurementHistory||[]).filter(x=>Number.isFinite(Number(x[metric])));if(!el)return;if(hist.length<2){el.innerHTML='<p class="small">Save at least two check-ins to draw a progress chart.</p>';return}const vals=hist.map(x=>Number(x[metric])),min=Math.min(...vals),max=Math.max(...vals),range=max-min||1,w=620,h=190,pad=28,pts=vals.map((v,i)=>[pad+i*(w-pad*2)/(vals.length-1),h-pad-(v-min)*(h-pad*2)/range]),path=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');el.innerHTML=`<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${metric} progress chart"><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="#dcece4"/><path class="chart-line" d="${path}"/>${pts.map((p,i)=>`<circle class="chart-point" cx="${p[0]}" cy="${p[1]}" r="5"><title>${formatDate(hist[i].date)}: ${vals[i]}</title></circle>`).join('')}<text x="${pad}" y="16" font-size="12" fill="#638075">${max}</text><text x="${pad}" y="${h-4}" font-size="12" fill="#638075">${min}</text></svg>`}

