try{init();recalc(false);day=d.days[key()]||blank();render();loadMeasurements();logDate.addEventListener('change',()=>loadSelectedDate(logDate.value));document.getElementById('saveMeasurementsBtn').addEventListener('click',()=>saveMeasurements(false));document.getElementById('skipMeasurementsBtn').addEventListener('click',()=>saveMeasurements(true));document.getElementById('progressMetric').addEventListener('change',renderProgressChart);document.getElementById('exportSaveBtn').addEventListener('click',exportSave);document.getElementById('importSaveBtn').addEventListener('click',()=>document.getElementById('importSaveInput').click());document.getElementById('importSaveInput').addEventListener('change',e=>importSaveFile(e.target.files[0]));document.getElementById('restoreBackupBtn').addEventListener('click',restoreSafetyBackup);document.getElementById('recoverBestBtn').addEventListener('click',recoverBestSave);updateDataStatus();updateRecoveryStatus();show(d.profile.onboardingComplete?'dash':'onboarding');document.documentElement.dataset.appReady='true';if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(console.error)}catch(err){console.error(err);const box=document.getElementById('appError');if(box){box.hidden=false;box.textContent='App error: '+err.message}}
